      if (i.op === "weekly_update") { need(i, "update"); const rec = rt.store.put("dil_cases", caseId, { case_id: caseId, loan_id: str(i, "loan_id"), last_update_on: today, last_update: str(i, "update") }, ctx.actor, ctx.now); ctx.events.append({ type: "liquidation.dil.weekly_update.logged", loanId: str(i, "loan_id"), actor: ctx.actor, payload: { case_id: caseId, on: today } }); return rec.data; }
      // Inbound records (valuation result, closing proceeds, DIL inspection, relocation disbursement, CA NOD rescission, 13.x sale date) are validated against the case's event stream by ops-12-9.ts and appended as the events the 12.9 timer rows are satisfied/armed by.
