      const rec = rt.store.put("liquidation_cases", caseId, { loan_id: str(i, "loan_id"), kind: str(i, "kind") || (prior?.kind as string | undefined) || "short_sale", status: str(i, "status") || (prior?.status as string | undefined) || "open", ...facts, ...changes, ...(str(i, "status") ? { [`${str(i, "status")}_on`]: today } : {}) }, ctx.actor, ctx.now);
